#pragma once

// Deterministic stand-in Agent for tests. It produces the same semantic
// activity a real Agent or MCP adapter must produce (streamed assistant
// replies with success, failure, and retry behavior, plus typed tool requests
// for the native coordinator) so the host, bridge, and page cannot
// special-case it. The app does not ship it; the harness installs it through
// AgentHost::set_agent. GUI-free.

#include "slic3r/GUI/JusPrin/Agent/AgentService.hpp"

#include <deque>

namespace Slic3r::GUI::JusPrin::Agent {

class DeterministicMockAgent : public IAgentService
{
public:
    // A compact, non-binary view of one sent attachment. Model/project files
    // reach the Agent only through `summary`, never as decoded bytes.
    struct AttachmentContext
    {
        std::string id;
        std::string name;
        std::string kind;
        std::string summary;
        bool        importable{false}; // a file-based model that can be imported
    };

    struct Reply
    {
        // Streamed in order; on error the stream fails after the chunks.
        std::vector<std::string>  chunks;
        std::optional<AgentError> error;
        // Submitted to the ToolExecutionCoordinator when the stream completes
        // successfully. The coordinator executes it through the workspace
        // contract.
        std::optional<ToolRequest> tool;
        int                        tool_run_ticks{1};
    };
