"""

import argparse
import json
import pathlib
import re
import sys

WHITESPACE = b" \t\r\n"


def common_prefix(a, b):
    """The length of the bytes `a` and `b` open with alike."""
    n = min(len(a), len(b))
    low, high = 0, n
    while low < high:  # halving: bodies are hundreds of kilobytes
        middle = (low + high + 1) // 2
        if a[:middle] == b[:middle]:
            low = middle
        else:
            high = middle - 1
    return low


def _spans(data):
    """Every value in a JSON document as (start, end, path), end exclusive.
    An object member's span starts at its key, so a byte of the key belongs
    to the member."""
    spans = []

    def skip(i):
        while i < len(data) and data[i] in WHITESPACE:
            i += 1
        return i

    def string(i):
        j = i + 1
        while data[j] != 0x22:  # "
            j += 2 if data[j] == 0x5C else 1  # a backslash escapes the next byte
        return j + 1, json.loads(data[i:j + 1])

    def value(i, path):
        i = skip(i)
        start = i
        if data[i] == 0x7B:  # {
            i = skip(i + 1)
            if data[i] == 0x7D:
                i += 1
            else:
                while True:
                    i = skip(i)
                    key_start = i
                    i, key = string(i)
                    i = skip(i) + 1  # the colon
                    i = value(i, path + [key])
                    spans.append((key_start, i, path + [key]))
                    i = skip(i)
                    i += 1
                    if data[i - 1] == 0x7D:
                        break
        elif data[i] == 0x5B:  # [
            i = skip(i + 1)
            if data[i] == 0x5D:
                i += 1
            else:
                index = 0
                while True:
                    i = value(i, path + [index])
                    index += 1
                    i = skip(i) + 1
                    if data[i - 1] == 0x5D:
                        break
        elif data[i] == 0x22:
            i, _ = string(i)
        else:
            while i < len(data) and data[i] not in b",]}" + WHITESPACE:
                i += 1
        spans.append((start, i, path))
        return i

    value(0, [])
    return spans


