                        // Anthropic: message_start's message.usage and message_delta's usage; Responses: response.usage.
                        for (const char* at : {"/usage", "/message/usage", "/response/usage"})
                            if (line.is_object() && line.contains(nlohmann::json::json_pointer(at)) && line.at(nlohmann::json::json_pointer(at)).is_object())
                                *usage << line.at(nlohmann::json::json_pointer(at)).dump() << '\n' << std::flush;
                    }
                }
